"""Response validation primitives shared by generated Bybit endpoints."""

from typing_extensions import Annotated, Any, Generic, TypedDict as _TypedDict, TypeVar
from datetime import datetime
from pydantic import BeforeValidator, ConfigDict, with_config

from typed_core.exceptions import ValidationError

from .util import timestamp as ts


@with_config(ConfigDict(extra='allow'))
class TypedDict(_TypedDict):
  """`TypedDict` base that tolerates undocumented extra fields from Bybit."""


Timestamp = Annotated[datetime, BeforeValidator(ts.parse)]

T = TypeVar('T')


class validator(Generic[T]):
  """Lazily-built pydantic adapter that raises `ValidationError` on mismatch."""

  def __init__(self, Type: Any):
    from pydantic import TypeAdapter

    self.adapter = TypeAdapter(Type)

  def json(self, data: str | bytes | bytearray) -> T:
    """Validate a raw JSON document."""
    from pydantic import ValidationError as PydanticValidationError

    try:
      return self.adapter.validate_json(data)
    except PydanticValidationError as e:
      raise ValidationError(*e.args) from e

  def python(self, data: Any) -> T:
    """Validate an already-decoded Python value."""
    from pydantic import ValidationError as PydanticValidationError

    try:
      return self.adapter.validate_python(data)
    except PydanticValidationError as e:
      raise ValidationError(*e.args) from e

  def __call__(self, data) -> T:
    if isinstance(data, str | bytes | bytearray):
      return self.json(data)
    return self.python(data)
